619	    fn render(&mut self, frame: &mut Frame, area: Rect, ctx: &RenderContext) -> Result<()> {
620	        // Standard layout (header=5, footer=2)
621	        let (header_chunk, content_chunk, footer_chunk) = create_standard_layout(area, 5, 3);
622	
623	        // Header
