725	    fn on_enter(&mut self, _ctx: &ScreenContext) -> Result<()> {
726	        // Reset to first setting
727	        self.state.list_state.select(Some(0));
728	        self.state.focus = SettingsFocus::List;
729	        self.state.option_index = 0;
730	        Ok(())
731	    }
732	}
