64	            SettingItem::EmbedCredentials => "Token in Remote URL",
65	        }
66	    }
67	
68	    #[must_use]
69	    pub fn from_index(index: usize, repo_mode: RepoMode) -> Option<SettingItem> {
70	        Self::all(repo_mode).get(index).copied()
71	    }
72	}
