110	    list_pane_area: Option<Rect>,
111	    /// Area of the options pane (for scroll hit-testing)
112	    options_pane_area: Option<Rect>,
113	}
114	
115	impl Default for SettingsScreen {
116	    fn default() -> Self {
117	        Self::new()
118	    }
119	}
