1	//! Shared test utilities for critical workflow integration tests.
2	//!
3	//! Provides `TestEnv` - a complete isolated DotState environment for testing,
4	//! with automatic cleanup via `TempDir`.
5	//!
6	//! ## E2E Tests with Real Services
7	//!
8	//! To test with actual service calls (SyncService, ProfileService, etc.),
9	//! use `.with_env_override()` on the builder. This sets environment variables
10	//! that redirect DotState's path functions to the test directories.
11	//!
12	//! **Important**: Tests using env overrides should run serially to avoid
13	//! conflicts. Run with: `cargo test --test workflow_sync -- --test-threads=1`
14	
15	use anyhow::{Context, Result};
16	use std::fs;
17	use std::os::unix::fs::symlink;
18	use std::path::{Path, PathBuf};
19	use std::sync::Mutex;
20	use tempfile::TempDir;
21	
22	use dotstate::config::{Config, RepoMode};
23	use dotstate::utils::profile_manifest::{ProfileInfo, ProfileManifest};
24	use dotstate::utils::symlink_manager::{SymlinkTracking, TrackedSymlink};
25	
26	/// Global mutex to ensure only one test uses env overrides at a time.
27	/// This prevents race conditions when multiple tests try to set env vars.
28	static ENV_MUTEX: Mutex<()> = Mutex::new(());
29	
30	/// Guard that restores environment variables when dropped.
31	struct EnvGuard {
32	    old_home: Option<String>,
33	    old_config: Option<String>,
34	    old_backup: Option<String>,
35	    #[allow(dead_code)]
36	    lock: std::sync::MutexGuard<'static, ()>,
37	}
38	
39	impl Drop for EnvGuard {
40	    fn drop(&mut self) {
41	        // Restore original env vars
42	        match &self.old_home {
43	            Some(v) => std::env::set_var("DOTSTATE_TEST_HOME", v),
44	            None => std::env::remove_var("DOTSTATE_TEST_HOME"),
45	        }
46	        match &self.old_config {
47	            Some(v) => std::env::set_var("DOTSTATE_TEST_CONFIG_DIR", v),
48	            None => std::env::remove_var("DOTSTATE_TEST_CONFIG_DIR"),
49	        }
50	        match &self.old_backup {
51	            Some(v) => std::env::set_var("DOTSTATE_TEST_BACKUP_DIR", v),
52	            None => std::env::remove_var("DOTSTATE_TEST_BACKUP_DIR"),
53	        }
54	    }
55	}
56	
57	/// A complete isolated DotState test environment.
58	///
59	/// Creates a temporary directory structure mimicking a real DotState setup:
60	/// - `home/` - fake home directory for dotfiles
61	/// - `repo/` - storage repository
62	/// - `config/` - config directory (~/.config/dotstate equivalent)
63	/// - `backups/` - backup directory
64	///
65	/// Automatically cleaned up when dropped. If env overrides are enabled,
66	/// the original environment is restored on drop.
67	#[allow(dead_code)]
68	pub struct TestEnv {
69	    temp_dir: TempDir,
70	    pub home_dir: PathBuf,
71	    pub repo_path: PathBuf,
72	    pub config_dir: PathBuf,
73	    pub backup_dir: PathBuf,
74	    env_guard: Option<EnvGuard>,
75	}
76	
77	#[allow(dead_code)]
78	impl TestEnv {
79	    /// Create a new TestEnvBuilder for fluent configuration.
80	    pub fn new() -> TestEnvBuilder {
81	        TestEnvBuilder::default()
82	    }
83	
84	    // ==================== Path Helpers ====================
85	
86	    /// Get absolute path for a file relative to the fake home directory.
87	    pub fn home_path(&self, relative: &str) -> PathBuf {
88	        self.home_dir.join(relative)
89	    }
90	
91	    /// Get absolute path for a file relative to the repository.
92	    pub fn repo_file_path(&self, relative: &str) -> PathBuf {
93	        self.repo_path.join(relative)
94	    }
95	
96	    /// Get the path for a profile's directory in the repo.
97	    /// Note: Profiles are stored directly at repo_path/<profile_name>/, not repo_path/profiles/<profile_name>/
98	    pub fn profile_path(&self, profile_name: &str) -> PathBuf {
99	        self.repo_path.join(profile_name)
100	    }

