#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_check_for_updates_setting_name() {
        assert_eq!(
            SettingItem::CheckForUpdates.name(),
            "Automatic Update Checks"
        );
    }

    #[test]
    fn test_apply_automatic_update_checks_enabled() {
        let mut config = crate::config::Config::default();
        config.updates.check_enabled = false;

        let result = SettingsScreen::apply_setting_to_config(
            &SettingsScreen::new(),
            "Automatic Update Checks",
            0,
        );

        assert!(result);
        assert!(config.updates.check_enabled);
    }

    #[test]
    fn test_apply_automatic_update_checks_disabled() {
        let mut config = crate::config::Config::default();
        config.updates.check_enabled = true;

        let result = SettingsScreen::apply_setting_to_config(
            &SettingsScreen::new(),
            "Automatic Update Checks",
            1,
        );

        assert!(result);
        assert!(!config.updates.check_enabled);
    }

    #[test]
    fn test_apply_setting_with_old_name_fails() {
        let mut config = crate::config::Config::default();
        config.updates.check_enabled = true;

        let result = SettingsScreen::apply_setting_to_config(
            &SettingsScreen::new(),
            "Check for Updates",
            1,
        );

        assert!(!result);
        assert!(config.updates.check_enabled);
    }
}

